55	const PROCESSING_FEE = 5;
56	
57	const FIRST_INSURANCE_SURCHARGE = 0.1;
58	
59	const BASE_PREMIUMS: Record<string, number> = {
60	  sword: 100,
61	  amulet: 60,
62	  staff: 80,
63	  potion: 40,
64	  rune: 25,
65	  moonstone: 25,
66	};
67	
68	const itemBasePremium = (item: Item): number => BASE_PREMIUMS[item.type];
69	
70	const BLOCK_SIZE = 3;
71	const BLOCK_BASE_PREMIUM = 60;
72	
73	const sumOfItemBasePremiums = (items: Item[]): number =>
74	  items.reduce((sum, item) => sum + itemBasePremium(item), 0);
75	
76	const itemsGroupedByType = (items: Item[]): Item[][] => {
77	  const byType = new Map<string, Item[]>();
78	  for (const item of items) {
79	    byType.set(item.type, [...(byType.get(item.type) ?? []), item]);
80	  }
81	  return [...byType.values()];
82	};
83	
84	const formsBlock = (sameTypeItems: Item[]): boolean => sameTypeItems.length === BLOCK_SIZE;
85	
86	const sameTypeBasePremium = (sameTypeItems: Item[]): number =>
87	  formsBlock(sameTypeItems) ? BLOCK_BASE_PREMIUM : sumOfItemBasePremiums(sameTypeItems);
88	
89	const policyBasePremium = (items: Item[]): number =>
90	  itemsGroupedByType(items).reduce(
91	    (sum, sameTypeItems) => sum + sameTypeBasePremium(sameTypeItems),
92	    0,
93	  );
94	
95	const withFirstInsuranceSurcharge = (policyBase: number): number =>
96	  policyBase + policyBase * FIRST_INSURANCE_SURCHARGE;
97	
98	const roundPremiumInMHPCOsFavor = Math.ceil;
99	
100	const HIGH_ENCHANTMENT_THRESHOLD = 5;
101	
102	const isCursed = (item: Item): boolean => item.cursed === true;
103	
104	const isHighlyEnchanted = (item: Item): boolean =>
105	  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD;
106	
107	interface RiskSurcharge {
108	  appliesTo: (item: Item) => boolean;
109	  rateOfBasePremium: number;
110	}
111	
112	const RISK_SURCHARGES: RiskSurcharge[] = [
113	  { appliesTo: isCursed, rateOfBasePremium: 0.5 },
114	  { appliesTo: isHighlyEnchanted, rateOfBasePremium: 0.3 },
115	];
116	
117	const itemRiskSurcharge = (item: Item): number =>
118	  RISK_SURCHARGES.filter((surcharge) => surcharge.appliesTo(item)).reduce(
119	    (sum, surcharge) => sum + itemBasePremium(item) * surcharge.rateOfBasePremium,
120	    0,
121	  );
122	
123	const totalRiskSurcharges = (items: Item[]): number =>
124	  items.reduce((sum, item) => sum + itemRiskSurcharge(item), 0);
125	
126	/** Who the policy is for, and where it sits in their history with the MHPCO. */
127	interface QuoteContext {
128	  customer: Customer;
129	  isFollowUpContract: boolean;
130	}
131	
132	const LOYALTY_DISCOUNT = 0.2;
133	const LOYALTY_THRESHOLD_YEARS = 2;
134	
135	const isLoyal = (context: QuoteContext): boolean =>
136	  context.customer.yearsWithMHPCO >= LOYALTY_THRESHOLD_YEARS;
137	
138	const loyaltyDiscount = (policyBase: number, context: QuoteContext): number =>
139	  isLoyal(context) ? policyBase * LOYALTY_DISCOUNT : 0;
140	
141	const FOLLOW_UP_CONTRACT_DISCOUNT = 0.15;
142	
143	const followUpContractDiscount = (policyBase: number, context: QuoteContext): number =>
144	  context.isFollowUpContract ? policyBase * FOLLOW_UP_CONTRACT_DISCOUNT : 0;
145	
146	const policyWidePremium = (policyBase: number, context: QuoteContext): number =>
147	  withFirstInsuranceSurcharge(policyBase) -
148	  loyaltyDiscount(policyBase, context) -
149	  followUpContractDiscount(policyBase, context);
150	
151	const premiumBeforeFee = (items: Item[], context: QuoteContext): number =>
152	  policyWidePremium(policyBasePremium(items), context) + totalRiskSurcharges(items);
153	
154	const quotePremium = (items: Item[], context: QuoteContext): number =>
155	  roundPremiumInMHPCOsFavor(premiumBeforeFee(items, context) + PROCESSING_FEE);
156	
157	const INSURANCE_VALUES: Record<string, number> = {
158	  sword: 1000,
159	  amulet: 600,
160	  staff: 800,
161	  potion: 400,
162	  rune: 250,
163	  moonstone: 250,
164	};
165	
166	const DEDUCTIBLE_PER_DAMAGE = 100;
167	const CAP_MULTIPLE_OF_INSURANCE_SUM = 2;
168	
169	const insuranceSum = (items: Item[]): number =>
170	  items.reduce((sum, item) => sum + INSURANCE_VALUES[item.type], 0);
171	
172	interface Policy {
173	  items: Item[];
174	  remainingCap: number;
175	}
176	
177	const damagePayout = (damage: Damage): number => damage.amount - DEDUCTIBLE_PER_DAMAGE;
178	
179	const settleClaim = (policy: Policy, incident: Incident): ClaimResult => {
180	  const payout = incident.damages.reduce((sum, damage) => sum + damagePayout(damage), 0);
181	  policy.remainingCap -= payout;
182	  return { payout, remainingCap: policy.remainingCap };
183	};
184	
185	export const runScenario = (scenario: Scenario): ScenarioResult => {
186	  const policies = new Map<number, Policy>();
187	  const results: StepResult[] = [];
188	
189	  scenario.steps.forEach((step, stepIndex) => {
190	    if (step.op === "quote") {
191	      policies.set(stepIndex, {
192	        items: step.items,
193	        remainingCap: insuranceSum(step.items) * CAP_MULTIPLE_OF_INSURANCE_SUM,
194	      });
195	      results.push({
196	        premium: quotePremium(step.items, {
197	          customer: scenario.customer,
198	          isFollowUpContract: policies.size > 1,
199	        }),
200	      });
201	      return;
202	    }
203	
204	    const policy = policies.get(step.policy);
205	    if (policy === undefined) {
206	      throw new Error(`Unknown policy: ${step.policy}`);
207	    }
208	    results.push(settleClaim(policy, step.incident));
209	  });
210	
211	  return { results };
212	};
