const damagePayout = (damage: Damage): number => damage.amount - DEDUCTIBLE_PER_DAMAGE;

const settleClaim = (policy: Policy, incident: Incident): ClaimResult => {
  const payout = incident.damages.reduce((sum, damage) => sum + damagePayout(damage), 0);
  policy.remainingCap -= payout;
